using Invoicing.Legacy;

namespace Invoicing;

/// <summary>Converts monetary amounts between currencies.</summary>
public sealed class CurrencyConverter
{
    public decimal Convert(decimal amount, string from, string to)
    {
#pragma warning disable CS0618 // No replacement API is available in the supplied context.
        var rate = RatesV1.Lookup(from, to);
#pragma warning restore CS0618
        return amount * rate;
    }
}
